"""Coherence-is-connectedness demonstration.

Builds every bracketing of a fixed word and verifies that they are pairwise
isomorphic in the parenthesization category (i.e. they flatten to the same word),
while being pairwise distinct as trees.
"""
from __future__ import annotations
from dataclasses import dataclass
from itertools import product
from typing import List, Union


@dataclass(frozen=True)
class Leaf:
    label: str


@dataclass(frozen=True)
class Node:
    left: "PTree"
    right: "PTree"


PTree = Union[Leaf, Node]


def flatten(t: PTree) -> List[str]:
    if isinstance(t, Leaf):
        return [t.label]
    return flatten(t.left) + flatten(t.right)


def show(t: PTree) -> str:
    if isinstance(t, Leaf):
        return t.label
    return f"({show(t.left)}.{show(t.right)})"


def bracketings(word: List[str]) -> List[PTree]:
    if len(word) == 1:
        return [Leaf(word[0])]
    out: List[PTree] = []
    for i in range(1, len(word)):
        for l, r in product(bracketings(word[:i]), bracketings(word[i:])):
            out.append(Node(l, r))
    return out


def main() -> None:
    word = ["a", "b", "c", "d"]
    trees = bracketings(word)
    print(f"{len(trees)} bracketings of {word}:")
    for t in trees:
        print("  ", show(t))
    pairwise_iso = all(flatten(s) == flatten(t) for s in trees for t in trees)
    distinct = len({show(t) for t in trees}) == len(trees)
    print("all pairwise isomorphic (same word)?", pairwise_iso)
    print("all distinct as trees?", distinct)


if __name__ == "__main__":
    main()

"""Strictification round-trip demonstration.

Verifies the two natural isomorphisms of the equivalence between the groupoid of
bracketings and the discrete category on words:
  * counit: flatten(of_list(word)) == word  (identity on the nose);
  * unit:   of_list(flatten(tree)) is isomorphic to tree (canonical normal form).
"""
from __future__ import annotations
from dataclasses import dataclass
from itertools import product
from typing import List, Union


@dataclass(frozen=True)
class Leaf:
    label: str


@dataclass(frozen=True)
class Node:
    left: "PTree"
    right: "PTree"


PTree = Union[Leaf, Node]


def flatten(t: PTree) -> List[str]:
    if isinstance(t, Leaf):
        return [t.label]
    return flatten(t.left) + flatten(t.right)


def of_list(word: List[str]) -> PTree:
    if len(word) == 1:
        return Leaf(word[0])
    return Node(Leaf(word[0]), of_list(word[1:]))


def bracketings(word: List[str]) -> List[PTree]:
    if len(word) == 1:
        return [Leaf(word[0])]
    out: List[PTree] = []
    for i in range(1, len(word)):
        for l, r in product(bracketings(word[:i]), bracketings(word[i:])):
            out.append(Node(l, r))
    return out


def main() -> None:
    for word in (["a"], ["a", "b"], ["a", "b", "c"], ["a", "b", "c", "d", "e"]):
        # counit: F(G(word)) == word
        assert flatten(of_list(word)) == word
        # unit: G(F(tree)) isomorphic to tree, for every bracketing
        for t in bracketings(word):
            assert flatten(of_list(flatten(t))) == flatten(t)
        print(f"word {word}: counit identity OK, unit iso OK "
              f"({len(bracketings(word))} bracketings collapse to 1 class)")
    print("Equivalence of categories verified on all tested words.")


if __name__ == "__main__":
    main()

"""Catalan census demonstration.

Cross-checks three computations of the number of bracketings of n+1 factors:
explicit enumeration, the closed form C_n = binom(2n,n)/(n+1), and the Segner
convolution recurrence C_{k+1} = sum_i C_i C_{k-i}.
"""
from __future__ import annotations
from itertools import product
from math import comb
from typing import List


def count_bracketings(n_factors: int) -> int:
    if n_factors == 1:
        return 1
    return sum(count_bracketings(i) * count_bracketings(n_factors - i)
               for i in range(1, n_factors))


def catalan_closed(n: int) -> int:
    return comb(2 * n, n) // (n + 1)


def catalan_segner(n: int) -> int:
    c: List[int] = [1]
    for k in range(n):
        c.append(sum(c[i] * c[k - i] for i in range(k + 1)))
    return c[n]


def main() -> None:
    print(" n+1 |  enum | closed | Segner")
    for n in range(0, 10):
        e = count_bracketings(n + 1)
        cf = catalan_closed(n)
        sg = catalan_segner(n)
        assert e == cf == sg
        print(f" {n + 1:>3} | {e:>5} | {cf:>6} | {sg:>6}")
    print("All three agree for n = 0..9.")


if __name__ == "__main__":
    main()

