from dataclasses import dataclass
from typing import List, Union


@dataclass(frozen=True)
class Leaf:
    label: str


@dataclass(frozen=True)
class Node:
    left: "PTree"
    right: "PTree"


PTree = Union[Leaf, Node]


def flatten(t: PTree) -> List[str]:
    """Post-order traversal: underlying word of a bracketing. O(#nodes)."""
    if isinstance(t, Leaf):
        return [t.label]
    return flatten(t.left) + flatten(t.right)


def of_list(word: List[str]) -> PTree:
    """Right fold: canonical right-nested bracketing of a word. O(len)."""
    if len(word) == 1:
        return Leaf(word[0])
    return Node(Leaf(word[0]), of_list(word[1:]))


def canonical(t: PTree) -> PTree:
    """Skeleton map: canonical representative of the iso class of t."""
    return of_list(flatten(t))

