from __future__ import annotations
from math import comb
from typing import List


def catalan_dp(n: int) -> List[int]:
    """Segner convolution DP: returns [C_0, ..., C_n] in O(n^2) operations."""
    c: List[int] = [1]
    for k in range(n):
        c.append(sum(c[i] * c[k - i] for i in range(k + 1)))
    return c


def catalan_closed(n: int) -> int:
    """Closed form C_n = binom(2n, n) / (n + 1) in O(n) big-int operations."""
    return comb(2 * n, n) // (n + 1)
